import java.util.*;

class Solution {
  public int countSubarrays(int[] nums, int k) {
    Map<Integer, Integer> right = new HashMap<>();
    right.put(0, 1);
    int balance = 0, pivot = -1;
    for (int i = 0; i < nums.length; i++) {
      if (nums[i] == k) pivot = i;
      else balance += nums[i] < k ? -1 : 1;
      if (pivot < 0) right.merge(balance, 1, Integer::sum);
    }
    long answer = 0;
    balance = 0;
    for (int i = pivot; i < nums.length; i++) {
      if (nums[i] != k) balance += nums[i] < k ? -1 : 1;
      answer += right.getOrDefault(-balance, 0);
      answer += right.getOrDefault(1 - balance, 0);
    }
    return (int) answer;
  }
}
